<?php
namespace App\Controllers\Clinica;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Models\Surgery;use App\Models\Patient;use App\Models\Catalog;use App\Services\SurgeryService;use Throwable;
class CirugiaController extends Controller{public function index(Request $r):void{$q=trim((string)$r->input('q',''));$c=new Catalog();$this->view('cirugias/index',['title'=>'Cirugías','surgeries'=>(new Surgery())->list(active_environment_id(),$q),'patients'=>(new Patient())->allByEnvironment(active_environment_id()),'procedures'=>$c->surgeryProcedures(),'anesthesiaTypes'=>$c->anesthesiaTypes(),'search'=>$q,'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function store(Request $r):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{(new SurgeryService())->create($r->all(),$r->files(),active_environment_id(),auth_id());Session::flash('success','Cirugía registrada.');}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/cirugias');}}
